style:
/* Durar Sheets (جداول درر). Paste into the same Custom HTML Block's Style field. */
/* Generated by build_agent_blocks.py from spreadsheet/spreadsheet.css. Edit the source, not this copy. */
:host {
  display: block;
}
.ds {
  --ds-accent: #0f766e;
  --ds-accent-fg: #ffffff;
  --ds-accent-text: #0d5f58;
  --ds-accent-soft: #d6efeb;
  --ds-sel-fill: rgba(15, 118, 110, 0.11);
  --ds-bg: #f3f4f6;
  --ds-surface: #ffffff;
  --ds-surface-2: #f8fafc;
  --ds-hover: #eef2f5;
  --ds-active: #e2e8ee;
  --ds-text: #1f2937;
  --ds-sub: #5b6573;
  --ds-muted: #8a94a3;
  --ds-line: #d8dde3;
  --ds-line-soft: #e8ebef;
  --ds-danger: #c62828;
  --ds-warn: #b45309;
  --ds-shadow: 0 10px 30px rgba(15, 23, 42, 0.16), 0 2px 6px rgba(15, 23, 42, 0.08);
  --ds-grid-bg: #ffffff;
  --ds-cell: #ffffff;
  --ds-cell-fg: #111111;
  --ds-gridline: #e1e3e6;
  --ds-head: #f6f7f8;
  --ds-head-fg: #5f6368;
  --ds-head-line: #d5d8dc;
  --ds-head-sel: #d3ece8;
  --ds-freeze: #aeb4bc;
  --ds-link: #0563c1;
  --ds-btn: #ffffff;
  --ds-radius: 8px;
  position: relative;
  display: flex;
  flex-direction: column;
  height: calc(100vh - 150px);
  min-height: 560px;
  overflow: hidden;
  border: 1px solid var(--ds-line);
  border-radius: 12px;
  background: var(--ds-bg);
  color: var(--ds-text);
  font: 13px/1.4 "Segoe UI", -apple-system, BlinkMacSystemFont, Inter, system-ui, Roboto, Tahoma, Arial, sans-serif;
  text-align: start;
  -webkit-font-smoothing: antialiased;
  isolation: isolate;
}
.ds[data-theme="dark"] {
  --ds-accent: #2dd4bf;
  --ds-accent-fg: #042f2b;
  --ds-accent-text: #5eead4;
  --ds-accent-soft: #134e48;
  --ds-sel-fill: rgba(45, 212, 191, 0.16);
  --ds-bg: #0f1419;
  --ds-surface: #171d24;
  --ds-surface-2: #1d242c;
  --ds-hover: #232b34;
  --ds-active: #2b3540;
  --ds-text: #e6e9ed;
  --ds-sub: #a3adb9;
  --ds-muted: #79838f;
  --ds-line: #2c353f;
  --ds-line-soft: #252d36;
  --ds-danger: #f87171;
  --ds-warn: #fbbf24;
  --ds-shadow: 0 12px 36px rgba(0, 0, 0, 0.55);
  --ds-grid-bg: #12171c;
  --ds-cell: #12171c;
  --ds-cell-fg: #e6e9ed;
  --ds-gridline: #262e37;
  --ds-head: #1a2028;
  --ds-head-fg: #a3adb9;
  --ds-head-line: #2f3842;
  --ds-head-sel: #143d39;
  --ds-freeze: #4b5563;
  --ds-link: #60a5fa;
  --ds-btn: #1d242c;
}
.ds *,
.ds *::before,
.ds *::after {
  box-sizing: border-box;
}
.ds [hidden] {
  display: none !important;
}
:where(.ds) button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
  margin: 0;
  cursor: pointer;
  text-align: inherit;
}
:where(.ds) button:disabled {
  cursor: default;
  opacity: 0.42;
}
.ds :focus-visible {
  outline: 2px solid var(--ds-accent);
  outline-offset: 1px;
}
.ds-i {
  width: 18px;
  height: 18px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  vertical-align: middle;
}
.ds-i .ds-swatch {
  stroke: #c00000;
}
.ds-i.spin {
  animation: ds-spin 1s linear infinite;
}
@keyframes ds-spin {
  to {
    transform: rotate(360deg);
  }
}
.ds-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.ds.ds-full {
  position: fixed;
  inset: 0;
  z-index: 1030;
  height: 100vh;
  border-radius: 0;
  border: 0;
}

/* ---------- title bar ---------- */
.ds-top {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 42px;
  padding: 4px 8px;
  background: var(--ds-accent);
  color: var(--ds-accent-fg);
}
.ds-filebtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 10px;
  border-radius: 6px;
  font-weight: 600;
}
.ds-filebtn:hover,
.ds-top .ds-icon:hover,
.ds-qat .ds-rb:hover {
  background: rgba(255, 255, 255, 0.16);
}
.ds[data-theme="dark"] .ds-filebtn:hover,
.ds[data-theme="dark"] .ds-top .ds-icon:hover,
.ds[data-theme="dark"] .ds-qat .ds-rb:hover {
  background: rgba(0, 0, 0, 0.14);
}
.ds-qat {
  display: flex;
  align-items: center;
  gap: 1px;
}
.ds-qat .ds-rb {
  width: 30px;
  height: 30px;
  justify-content: center;
  color: inherit;
}
.ds-qat .ds-rb.more {
  width: 20px;
}
.ds-titlebox {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.ds-title {
  min-width: 80px;
  max-width: 420px;
  width: 40%;
  height: 30px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font: 600 14px/1 inherit;
  text-align: center;
  text-overflow: ellipsis;
}
.ds-title:hover {
  border-color: rgba(255, 255, 255, 0.35);
}
.ds-title:focus {
  background: rgba(255, 255, 255, 0.95);
  color: #1f2937;
  outline: none;
}
.ds-savestate {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  opacity: 0.88;
  white-space: nowrap;
}
.ds-savestate .ds-i {
  width: 16px;
  height: 16px;
}
.ds-savestate[data-state="error"],
.ds-savestate[data-state="offline"] {
  opacity: 1;
  font-weight: 600;
}
.ds-people {
  display: flex;
  gap: 2px;
}
.ds-avatar {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: none;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.85);
  color: #fff;
  font: 700 11px/1 inherit;
  background: #64748b;
}
.ds-avatar .ds-i {
  width: 15px;
  height: 15px;
}
.ds-avatar.sm {
  width: 24px;
  height: 24px;
  border-width: 0;
}
.ds-avatar.more {
  background: rgba(0, 0, 0, 0.25);
}
.ds-btn.ds-share {
  background: rgba(255, 255, 255, 0.95);
  color: var(--ds-accent-text);
  border-color: transparent;
}
.ds[data-theme="dark"] .ds-btn.ds-share {
  background: #042f2b;
  color: #5eead4;
}
.ds-top .ds-icon {
  color: inherit;
}

/* ---------- ribbon tabs ---------- */
.ds-tabs {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0 8px;
  background: var(--ds-surface);
  border-bottom: 1px solid var(--ds-line-soft);
  overflow-x: auto;
  scrollbar-width: none;
}
.ds-tabs::-webkit-scrollbar {
  display: none;
}
.ds-tab {
  position: relative;
  flex: none;
  padding: 9px 12px 8px;
  color: var(--ds-sub);
  font-weight: 500;
  white-space: nowrap;
}
.ds-tab:hover {
  color: var(--ds-text);
  background: var(--ds-hover);
  border-radius: 6px 6px 0 0;
}
.ds-tab[aria-selected="true"] {
  color: var(--ds-accent-text);
  font-weight: 600;
}
.ds-tab[aria-selected="true"]::after {
  content: "";
  position: absolute;
  left: 10px;
  right: 10px;
  bottom: 0;
  height: 3px;
  border-radius: 3px 3px 0 0;
  background: var(--ds-accent);
}
.ds-tab.ctx {
  color: #7c3aed;
}
.ds[data-theme="dark"] .ds-tab.ctx {
  color: #c4b5fd;
}
.ds-tab.file {
  display: none;
}
.ds-tellme {
  margin-inline-start: auto;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 8px;
  height: 28px;
  border: 1px solid var(--ds-line);
  border-radius: 14px;
  background: var(--ds-surface-2);
  color: var(--ds-muted);
  flex: none;
}
.ds-tellme .ds-i {
  width: 15px;
  height: 15px;
}
.ds-tellme input {
  width: 170px;
  border: 0;
  background: transparent;
  color: var(--ds-text);
  font: inherit;
  outline: none;
}
.ds-ribbontoggle {
  flex: none;
}
.ds.ribbon-min .ds-ribbontoggle .ds-i {
  transform: rotate(180deg);
}

/* ---------- ribbon ---------- */
.ds-ribbon {
  display: flex;
  align-items: stretch;
  gap: 0;
  min-height: 96px;
  padding: 4px 6px 0;
  background: var(--ds-surface);
  border-bottom: 1px solid var(--ds-line);
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
}
.ds.ribbon-min:not(.ribbon-peek) .ds-ribbon {
  display: none;
}
.ds-group {
  display: flex;
  flex-direction: column;
  flex: none;
  padding: 0 6px;
  border-inline-end: 1px solid var(--ds-line-soft);
}
.ds-gitems {
  display: flex;
  align-items: flex-start;
  gap: 2px;
  flex: 1;
}
.ds-gitems.stack {
  flex-direction: column;
  gap: 3px;
}
.ds-group > footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: 20px;
  color: var(--ds-muted);
  font-size: 11px;
  white-space: nowrap;
}
.ds-launch {
  color: var(--ds-muted);
}
.ds-launch .ds-i {
  width: 12px;
  height: 12px;
}
.ds-row {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}
.ds-gitems .ds-row {
  flex-wrap: nowrap;
  gap: 1px;
}
.ds-col {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.ds-rb {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  min-width: 28px;
  padding: 0 5px;
  border-radius: 5px;
  color: var(--ds-text);
  white-space: nowrap;
}
.ds-rb:hover:not(:disabled) {
  background: var(--ds-hover);
}
.ds-rb.on {
  background: var(--ds-accent-soft);
  color: var(--ds-accent-text);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ds-accent) 35%, transparent);
}
.ds-rb em {
  font-style: normal;
  font-size: 12.5px;
}
.ds-rb.big {
  flex-direction: column;
  justify-content: flex-start;
  gap: 3px;
  height: 68px;
  min-width: 52px;
  max-width: 90px;
  padding: 6px 6px 4px;
  white-space: normal;
  text-align: center;
}
.ds-rb.big > span:first-child .ds-i {
  width: 26px;
  height: 26px;
  stroke-width: 1.5;
}
.ds-rb.big em {
  font-size: 11.5px;
  line-height: 1.2;
}
.ds-rb.menu .ds-caret .ds-i {
  width: 11px;
  height: 11px;
}
.ds-rb.big.menu .ds-caret {
  margin-top: -2px;
}
.ds-split {
  display: inline-flex;
  align-items: stretch;
  border-radius: 5px;
}
.ds-split:hover {
  box-shadow: inset 0 0 0 1px var(--ds-line);
}
.ds-split > .ds-rb:first-child {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}
.ds-split > .ds-rb.more {
  min-width: 14px;
  width: 14px;
  padding: 0;
  justify-content: center;
  border-start-start-radius: 0;
  border-end-start-radius: 0;
}
.ds-split > .ds-rb.more .ds-i {
  width: 11px;
  height: 11px;
}
.ds-split.big {
  flex-direction: column;
}
.ds-split.big > .ds-rb.big {
  height: 50px;
  border-radius: 5px 5px 0 0;
}
.ds-split.big > .ds-rb.more {
  width: auto;
  height: 18px;
  border-radius: 0 0 5px 5px;
}
/* fitRibbon(): small labels go first, then big ones; titles keep the names */
.ds-ribbon.rb-c1 .ds-rb:not(.big) em,
.ds-ribbon.rb-c2 .ds-rb.big em {
  display: none;
}
.ds-ribbon.rb-c2 .ds-rb.big {
  min-width: 40px;
  padding: 8px 4px 4px;
}
.ds-rsel {
  height: 28px;
  padding: 0 6px;
  border: 1px solid var(--ds-line);
  border-radius: 5px;
  background: var(--ds-surface);
  color: var(--ds-text);
  font: inherit;
}
.ds-rsel.font {
  width: 136px;
}
.ds-rsel.size {
  width: 56px;
}
.ds-rsel.numfmt {
  width: 140px;
}
.ds-small {
  font-size: 11.5px;
  color: var(--ds-sub);
}
.ds-opts {
  gap: 2px 14px;
  font-size: 12.5px;
}

/* ---------- formula bar ---------- */
.ds-fbar {
  display: flex;
  align-items: stretch;
  gap: 4px;
  padding: 4px 8px;
  background: var(--ds-surface);
  border-bottom: 1px solid var(--ds-line);
}
.ds.no-fbar .ds-fbar {
  display: none;
}
.ds-namewrap {
  display: flex;
  align-items: center;
  width: 128px;
  flex: none;
  border: 1px solid var(--ds-line);
  border-radius: 5px;
  background: var(--ds-surface);
}
.ds-namebox {
  width: 100%;
  min-width: 0;
  height: 26px;
  padding: 0 6px;
  border: 0;
  background: transparent;
  color: var(--ds-text);
  font: 500 12.5px/1 "Segoe UI", system-ui, sans-serif;
  outline: none;
}
.ds-namedrop {
  width: 20px !important;
  height: 26px !important;
}
.ds-namedrop .ds-i {
  width: 12px;
  height: 12px;
}
.ds-fxbtns {
  display: flex;
  align-items: center;
  gap: 1px;
  color: var(--ds-muted);
}
.ds-fxbtns .ds-icon {
  width: 26px;
  height: 26px;
}
.ds-fxbtns .ds-fxcancel,
.ds-fxbtns .ds-fxok {
  display: none;
}
.ds:has(.ds-editwrap.on) .ds-fxcancel,
.ds:has(.ds-editwrap.on) .ds-fxok {
  display: inline-grid;
}
.ds-fxfn {
  font-style: italic;
}
.ds-fxwrap {
  position: relative;
  flex: 1;
  min-width: 0;
  border: 1px solid var(--ds-line);
  border-radius: 5px;
  background: var(--ds-surface);
}
.ds-fx,
.ds-fxhl {
  display: block;
  width: 100%;
  height: 28px;
  margin: 0;
  padding: 4px 8px;
  border: 0;
  font: 13px/20px Consolas, "Cascadia Mono", "SF Mono", Menlo, "Segoe UI", monospace;
  white-space: pre-wrap;
  word-break: break-all;
  overflow: auto;
  tab-size: 2;
}
.ds-fx {
  position: relative;
  z-index: 1;
  resize: none;
  background: transparent;
  color: var(--ds-text);
  outline: none;
}
.ds-fxhl {
  position: absolute;
  inset: 0;
  color: transparent;
  pointer-events: none;
}
.ds-fxwrap.formula .ds-fx {
  color: transparent;
  caret-color: var(--ds-text);
}
.ds-fxwrap.formula .ds-fxhl {
  color: var(--ds-text);
}
.ds-fxexpand {
  width: 26px;
  height: 28px;
  color: var(--ds-muted);
}
.ds.fx-tall .ds-fxexpand .ds-i {
  transform: rotate(180deg);
}
.ds-fxhl .fn,
.ds-edithl .fn {
  color: #7c3aed;
}
.ds-fxhl .str,
.ds-edithl .str {
  color: #b45309;
}
.ds-fxhl .num,
.ds-edithl .num {
  color: #0369a1;
}
.ds-fxhl .err,
.ds-edithl .err,
.ds-fxhl .bad,
.ds-edithl .bad {
  color: #dc2626;
}
.ds-fxhl .bool,
.ds-edithl .bool,
.ds-fxhl .nm,
.ds-edithl .nm {
  color: #0f766e;
}
.ds[data-theme="dark"] .ds-fxhl .fn,
.ds[data-theme="dark"] .ds-edithl .fn {
  color: #c4b5fd;
}
.ds[data-theme="dark"] .ds-fxhl .str,
.ds[data-theme="dark"] .ds-edithl .str {
  color: #fbbf24;
}
.ds[data-theme="dark"] .ds-fxhl .num,
.ds[data-theme="dark"] .ds-edithl .num {
  color: #7dd3fc;
}

/* ---------- grid area ---------- */
.ds-main {
  position: relative;
  display: flex;
  flex: 1;
  min-height: 0;
}
.ds-gridarea {
  position: relative;
  flex: 1;
  min-width: 0;
  background: var(--ds-grid-bg);
}
.ds-scroller {
  position: absolute;
  inset: 0;
  overflow: auto;
  overscroll-behavior: contain;
  outline: none;
  scrollbar-width: thin;
}
.ds-sizer {
  position: relative;
}
.ds-stage {
  position: sticky;
  top: 0;
  left: 0;
  overflow: hidden;
  touch-action: pan-x pan-y;
}
.ds-canvas {
  display: block;
  cursor: cell;
  user-select: none;
  -webkit-user-select: none;
}
.ds-canvas[data-cursor="col-resize"] {
  cursor: col-resize;
}
.ds-canvas[data-cursor="row-resize"] {
  cursor: row-resize;
}
.ds-canvas[data-cursor="s-resize"] {
  cursor: s-resize;
}
.ds-canvas[data-cursor="e-resize"] {
  cursor: e-resize;
}
.ds-canvas[data-cursor="pointer"] {
  cursor: pointer;
}
.ds-canvas[data-cursor="crosshair"] {
  cursor: crosshair;
}
.ds-canvas[data-cursor="move"] {
  cursor: move;
}
.ds-objects {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.ds-obj {
  position: absolute;
  left: 0;
  top: 0;
  pointer-events: auto;
  border-radius: 6px;
  outline: none;
  transform-origin: 0 0;
}
.ds-obj > svg {
  display: block;
  border-radius: 6px;
}
.ds-obj.on {
  box-shadow: 0 0 0 2px var(--ds-accent);
}
.ds-hdl {
  position: absolute;
  display: none;
  width: 9px;
  height: 9px;
  border: 1.5px solid var(--ds-accent);
  border-radius: 50%;
  background: var(--ds-surface);
}
.ds-obj.on .ds-hdl {
  display: block;
}
.ds-hdl.nw {
  left: -5px;
  top: -5px;
  cursor: nwse-resize;
}
.ds-hdl.n {
  left: calc(50% - 5px);
  top: -5px;
  cursor: ns-resize;
}
.ds-hdl.ne {
  right: -5px;
  top: -5px;
  cursor: nesw-resize;
}
.ds-hdl.e {
  right: -5px;
  top: calc(50% - 5px);
  cursor: ew-resize;
}
.ds-hdl.se {
  right: -5px;
  bottom: -5px;
  cursor: nwse-resize;
}
.ds-hdl.s {
  left: calc(50% - 5px);
  bottom: -5px;
  cursor: ns-resize;
}
.ds-hdl.sw {
  left: -5px;
  bottom: -5px;
  cursor: nesw-resize;
}
.ds-hdl.w {
  left: -5px;
  top: calc(50% - 5px);
  cursor: ew-resize;
}
.ds-chartmsg {
  display: grid;
  place-items: center;
  height: 100%;
  border: 1px dashed var(--ds-line);
  border-radius: 6px;
  background: var(--ds-surface);
  color: var(--ds-muted);
}
.ds-slicer {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  border: 1px solid var(--ds-line);
  border-radius: 6px;
  background: var(--ds-surface);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  font-size: calc(12px * var(--z, 1));
}
.ds-slicer header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  border-bottom: 1px solid var(--ds-line-soft);
}
.ds-sliceritems {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px;
  overflow: auto;
}
.ds-slicerbtn {
  padding: 4px 8px;
  border: 1px solid var(--ds-line);
  border-radius: 4px;
  background: var(--ds-surface-2);
  color: var(--ds-muted);
  text-align: start;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-slicerbtn.on {
  background: var(--ds-accent-soft);
  border-color: var(--ds-accent);
  color: var(--ds-text);
}
.ds-slicerclear .ds-i {
  width: 14px;
  height: 14px;
}

/* the in-cell editor (also the keyboard sink while not editing) */
.ds-editwrap {
  position: absolute;
  z-index: 3;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}
.ds-editwrap.on {
  opacity: 1;
  pointer-events: auto;
  background: var(--ds-cell);
  box-shadow: 0 0 0 2px var(--ds-accent), 0 4px 14px rgba(0, 0, 0, 0.18);
}
.ds-editor,
.ds-edithl,
.ds-rich {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 1px 4px;
  border: 0;
  outline: none;
  overflow: hidden;
  white-space: pre-wrap;
  word-break: break-word;
  font: 14.6px/20px Calibri, Carlito, "Segoe UI", sans-serif;
  tab-size: 2;
}
.ds-editor {
  z-index: 1;
  resize: none;
  background: transparent;
  color: var(--ds-cell-fg);
  caret-color: var(--ds-cell-fg);
}
.ds-edithl {
  color: transparent;
  pointer-events: none;
}
.ds-editwrap.formula .ds-editor {
  color: transparent;
}
.ds-editwrap.formula .ds-edithl {
  color: var(--ds-cell-fg);
}
.ds-rich {
  z-index: 2;
  background: var(--ds-cell);
  color: var(--ds-cell-fg);
}
.ds-dvbtn {
  position: absolute;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 20px;
  border: 1px solid var(--ds-line);
  border-radius: 0 3px 3px 0;
  background: var(--ds-surface);
  color: var(--ds-sub);
}
.ds-dvbtn .ds-i {
  width: 13px;
  height: 13px;
}
.ds-fillopt {
  position: absolute;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 24px;
  height: 22px;
  border: 1px solid var(--ds-line);
  border-radius: 4px;
  background: var(--ds-surface);
  color: var(--ds-sub);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12);
}
.ds-fillopt .ds-i {
  width: 14px;
  height: 14px;
}

/* ---------- side panel ---------- */
.ds-side {
  display: flex;
  flex-direction: column;
  width: 340px;
  flex: none;
  border-inline-start: 1px solid var(--ds-line);
  background: var(--ds-surface);
}
.ds-side > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid var(--ds-line-soft);
}
.ds-side h2 {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
}
.ds-sidebody {
  flex: 1;
  overflow: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ---------- sheet tabs and status bar ---------- */
.ds-sheetbar {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 34px;
  padding: 0 6px;
  background: var(--ds-surface);
  border-top: 1px solid var(--ds-line);
}
.ds-sheettabs {
  display: flex;
  align-items: stretch;
  gap: 2px;
  height: 100%;
  overflow-x: auto;
  scrollbar-width: none;
  flex: 1;
}
.ds-sheettabs::-webkit-scrollbar {
  display: none;
}
.ds-sheettab {
  --tab: transparent;
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  max-width: 200px;
  padding: 0 14px;
  color: var(--ds-sub);
  white-space: nowrap;
  border-bottom: 3px solid var(--tab);
}
.ds-sheettab span {
  overflow: hidden;
  text-overflow: ellipsis;
}
.ds-sheettab:hover {
  background: var(--ds-hover);
}
.ds-sheettab.on {
  color: var(--ds-accent-text);
  font-weight: 600;
  background: var(--ds-surface-2);
  box-shadow: inset 0 3px 0 var(--ds-accent);
}
.ds-sheettab.drop {
  box-shadow: inset 3px 0 0 var(--ds-accent);
}
.ds-lock .ds-i {
  width: 12px;
  height: 12px;
}
.ds-tabinput {
  width: 140px;
  margin: 3px 0;
  padding: 0 6px;
  border: 1px solid var(--ds-accent);
  border-radius: 4px;
  background: var(--ds-surface);
  color: var(--ds-text);
  font: inherit;
}
.ds-status {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 28px;
  padding: 0 10px;
  background: var(--ds-surface-2);
  border-top: 1px solid var(--ds-line-soft);
  color: var(--ds-sub);
  font-size: 12px;
  white-space: nowrap;
}
.ds-mode {
  min-width: 46px;
}
.ds-calcstate.warn {
  color: var(--ds-warn);
  font-weight: 600;
}
.ds-msg {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ds-stats {
  display: flex;
  gap: 14px;
  cursor: context-menu;
}
.ds-stats b {
  color: var(--ds-text);
  font-weight: 600;
}
.ds-views,
.ds-zoom {
  display: flex;
  align-items: center;
  gap: 2px;
}
.ds-views .ds-icon,
.ds-zoom .ds-icon {
  width: 24px;
  height: 24px;
}
.ds-views .ds-icon .ds-i,
.ds-zoom .ds-icon .ds-i {
  width: 15px;
  height: 15px;
}
.ds-views .on {
  color: var(--ds-accent-text);
  background: var(--ds-accent-soft);
}
.ds-zoom input {
  width: 100px;
  accent-color: var(--ds-accent);
}
.ds-zoomval {
  min-width: 42px;
  text-align: center;
}

/* ---------- controls ---------- */
.ds-icon {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: none;
  border-radius: 6px;
  color: var(--ds-sub);
}
.ds-icon:hover:not(:disabled) {
  background: var(--ds-hover);
  color: var(--ds-text);
}
.ds-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 32px;
  padding: 0 14px;
  border: 1px solid var(--ds-line);
  border-radius: 6px;
  background: var(--ds-surface);
  color: var(--ds-text);
  font-weight: 500;
  white-space: nowrap;
}
.ds-btn:hover:not(:disabled) {
  background: var(--ds-hover);
}
.ds-btn.primary {
  border-color: var(--ds-accent);
  background: var(--ds-accent);
  color: var(--ds-accent-fg);
}
.ds-btn.primary:hover:not(:disabled) {
  filter: brightness(1.07);
  background: var(--ds-accent);
}
.ds-btn.danger {
  border-color: var(--ds-danger);
  background: var(--ds-danger);
  color: #fff;
}
.ds-link {
  color: var(--ds-link);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.ds-input {
  width: 100%;
  min-height: 32px;
  padding: 5px 9px;
  border: 1px solid var(--ds-line);
  border-radius: 6px;
  background: var(--ds-surface);
  color: var(--ds-text);
  font: inherit;
}
.ds-input:focus {
  border-color: var(--ds-accent);
  outline: none;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--ds-accent) 22%, transparent);
}
select.ds-input[size] {
  min-height: 120px;
  padding: 4px;
}
textarea.ds-input {
  resize: vertical;
}
.ds-code {
  font: 12.5px/1.5 Consolas, "Cascadia Mono", Menlo, monospace;
  white-space: pre;
}
.ds-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 10px;
  min-width: 0;
}
.ds-field > span:first-child {
  color: var(--ds-sub);
  font-size: 12px;
  font-weight: 500;
}
.ds-field small {
  color: var(--ds-muted);
}
.ds-label {
  margin: 6px 0 4px;
  color: var(--ds-sub);
  font-size: 12px;
  font-weight: 600;
}
.ds-check {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 3px 0;
  cursor: pointer;
}
.ds-check input {
  width: 15px;
  height: 15px;
  accent-color: var(--ds-accent);
}
.ds-check small {
  margin-inline-start: auto;
  color: var(--ds-muted);
}
.ds-stack {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ds-grid2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 14px;
  align-items: start;
}
.ds-grid3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 12px;
}
.ds-cols2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 14px;
}
.ds-cols3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 10px;
}
.ds-note {
  margin: 4px 0;
  color: var(--ds-sub);
  font-size: 12.5px;
}
.ds-note.err {
  color: var(--ds-danger);
}
.ds-pre {
  white-space: pre-wrap;
  margin: 0;
}
.ds-mono,
.mono {
  font-family: Consolas, "Cascadia Mono", Menlo, monospace;
  font-size: 12px;
}
fieldset {
  margin: 0 0 10px;
  padding: 6px 10px 8px;
  border: 1px solid var(--ds-line-soft);
  border-radius: 6px;
}
legend {
  padding: 0 4px;
  color: var(--ds-sub);
  font-size: 12px;
  font-weight: 600;
}
.ds-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}
.ds-table th,
.ds-table td {
  padding: 5px 8px;
  border-bottom: 1px solid var(--ds-line-soft);
  text-align: start;
  vertical-align: top;
}
.ds-table th {
  color: var(--ds-sub);
  font-weight: 600;
  background: var(--ds-surface-2);
}
.ds-table tr:hover td {
  background: var(--ds-hover);
}
.ds-actions {
  white-space: nowrap;
  text-align: end !important;
}
.ds-actions .ds-icon {
  width: 26px;
  height: 26px;
}
.ds-rangefield {
  display: flex;
  gap: 4px;
}
.ds-rangefield .ds-icon {
  border: 1px solid var(--ds-line);
}
.ds kbd {
  padding: 1px 5px;
  border: 1px solid var(--ds-line);
  border-radius: 4px;
  background: var(--ds-surface-2);
  font: 11px/1.4 "Segoe UI", system-ui, sans-serif;
  color: var(--ds-sub);
}

/* ---------- popups: menus, popovers, dialogs, toasts ---------- */
.ds-layer {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
}
.ds-layer > * {
  pointer-events: auto;
}
.ds-menu,
.ds-pop {
  position: absolute;
  min-width: 200px;
  max-width: min(420px, 92vw);
  max-height: min(70vh, 560px);
  overflow: auto;
  padding: 5px;
  border: 1px solid var(--ds-line);
  border-radius: 8px;
  background: var(--ds-surface);
  box-shadow: var(--ds-shadow);
}
.ds-menu.sub {
  position: absolute;
}
.ds-menu hr {
  margin: 4px 2px;
  border: 0;
  border-top: 1px solid var(--ds-line-soft);
}
.ds-menuhead {
  padding: 6px 8px 3px;
  color: var(--ds-muted);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.ds-mi {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 30px;
  padding: 4px 8px;
  border-radius: 5px;
  color: var(--ds-text);
  text-align: start;
}
.ds-mi:hover:not(:disabled),
.ds-mi:focus-visible {
  background: var(--ds-hover);
  outline: none;
}
.ds-mic {
  display: inline-grid;
  place-items: center;
  width: 18px;
  flex: none;
  color: var(--ds-sub);
}
.ds-mic .ds-i {
  width: 16px;
  height: 16px;
}
.ds-mil {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-mis .ds-i {
  width: 12px;
  height: 12px;
}
.ds-mi kbd {
  margin-inline-start: 12px;
}
.ds-sw {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.15);
}
.ds-sw.none {
  background: linear-gradient(135deg, transparent 45%, #d32f2f 46%, #d32f2f 54%, transparent 55%), #fff;
}
.ds-scale {
  display: inline-block;
  width: 46px;
  height: 12px;
  margin-inline-end: 8px;
  border-radius: 2px;
  vertical-align: middle;
}
.ds-themesw {
  display: inline-flex;
  gap: 1px;
  margin-inline-end: 8px;
  vertical-align: middle;
}
.ds-themesw b {
  width: 9px;
  height: 14px;
}
.ds-colors {
  width: 248px;
}
.ds-swatches {
  display: grid;
  grid-template-columns: repeat(10, 20px);
  gap: 3px;
  padding: 2px 6px 6px;
}
.ds-swatch {
  width: 20px;
  height: 20px;
  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.12) !important;
}
.ds-swatch:hover {
  transform: scale(1.15);
  box-shadow: 0 0 0 2px var(--ds-accent);
}
.ds-more input[type="color"] {
  width: 28px;
  height: 22px;
  margin-inline-start: auto;
  padding: 0;
  border: 0;
  background: none;
}
.ds-tstyles {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
  padding: 4px 6px 8px;
}
.ds-tstyle {
  display: flex;
  flex-direction: column;
  gap: 1px;
  width: 52px;
  padding: 3px;
  border: 1px solid var(--ds-line);
  border-radius: 4px;
  background: #fff;
}
.ds-tstyle:hover {
  box-shadow: 0 0 0 2px var(--ds-accent);
}
.ds-tstyle i {
  height: 7px;
}
.ds-cstyles {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  width: 400px;
  padding: 5px;
}
.ds-cstyle {
  padding: 7px 6px;
  border: 1px solid var(--ds-line-soft);
  border-radius: 4px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: center;
  color: #1f2937;
  background: #fff;
}
.ds-cstyle:hover {
  box-shadow: 0 0 0 2px var(--ds-accent);
}
.ds-scrim {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(15, 23, 42, 0.32);
  pointer-events: auto;
}
.ds-scrim.modeless {
  background: transparent;
  pointer-events: none;
  place-items: start end;
}
.ds-scrim.modeless .ds-dialog {
  pointer-events: auto;
  margin-top: 60px;
}
.ds-dialog {
  display: flex;
  flex-direction: column;
  width: min(460px, 100%);
  max-height: calc(100% - 20px);
  border: 1px solid var(--ds-line);
  border-radius: 12px;
  background: var(--ds-surface);
  box-shadow: var(--ds-shadow);
  animation: ds-pop 0.14s ease-out;
}
.ds-dialog.wide {
  width: min(760px, 100%);
}
.ds-dialog.print {
  width: min(1100px, 100%);
  height: calc(100% - 20px);
}
@keyframes ds-pop {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.98);
  }
}
.ds-dialog > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px 8px 18px;
}
.ds-dialog h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
}
.ds-dbody {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 6px 18px 12px;
}
.ds-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
  padding: 10px 14px 14px;
  border-top: 1px solid var(--ds-line-soft);
}
.ds-dialog > footer .ds-btn:first-child:not(.primary) {
  margin-inline-end: auto;
}
.ds-dtabs {
  display: flex;
  gap: 2px;
  margin-bottom: 12px;
  border-bottom: 1px solid var(--ds-line);
  overflow-x: auto;
}
.ds-dtab {
  padding: 7px 12px;
  color: var(--ds-sub);
  border-bottom: 2px solid transparent;
  white-space: nowrap;
}
.ds-dtab[aria-selected="true"] {
  color: var(--ds-accent-text);
  border-bottom-color: var(--ds-accent);
  font-weight: 600;
}
.ds-nfpane {
  display: grid;
  grid-template-columns: 170px 1fr;
  gap: 14px;
}
.ds-nfprev {
  min-height: 30px;
  margin-bottom: 10px;
  padding: 5px 9px;
  border: 1px solid var(--ds-line-soft);
  border-radius: 6px;
  background: var(--ds-surface-2);
  font: 14px Calibri, "Segoe UI", sans-serif;
}
.ds-bprev {
  position: relative;
  width: 200px;
  height: 120px;
  margin: 4px 0;
  border: 1px dashed var(--ds-line);
  background: #fff;
}
.ds-bedge {
  position: absolute;
  --b: #000;
}
.ds-bedge.top,
.ds-bedge.bottom {
  left: 10px;
  right: 10px;
  height: 10px;
}
.ds-bedge.top {
  top: 5px;
}
.ds-bedge.bottom {
  bottom: 5px;
}
.ds-bedge.left,
.ds-bedge.right {
  top: 10px;
  bottom: 10px;
  width: 10px;
}
.ds-bedge.left {
  left: 5px;
}
.ds-bedge.right {
  right: 5px;
}
.ds-bedge.dd,
.ds-bedge.du {
  left: 40%;
  width: 20%;
  top: 40%;
  height: 20%;
}
.ds-bedge.du {
  top: 60%;
}
.ds-bedge.top.on {
  border-top: 2px solid var(--b);
}
.ds-bedge.bottom.on {
  border-bottom: 2px solid var(--b);
}
.ds-bedge.left.on {
  border-left: 2px solid var(--b);
}
.ds-bedge.right.on {
  border-right: 2px solid var(--b);
}
.ds-bedge:hover {
  background: rgba(15, 118, 110, 0.12);
}
.ds-btext {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #6b7280;
  pointer-events: none;
}
.ds-cfprev {
  display: inline-block;
  padding: 4px 10px;
  border: 1px solid var(--ds-line-soft);
  border-radius: 4px;
  background: #fff;
  color: #111;
}
.ds-styleed {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
}
.ds-sortlevel,
.ds-seriesrow {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}
.ds-sortlevel .ds-input {
  width: auto;
  min-width: 120px;
}
.ds-sortlevel .ds-label {
  min-width: 60px;
  margin: 0;
}
.ds-seriesrow b {
  flex: 1 1 100%;
  font-weight: 600;
}
.ds-seriesrow select {
  flex: 1;
}
.ds-findresults {
  max-height: 220px;
  overflow: auto;
}
.ds-findresults tr {
  cursor: pointer;
}
.ds-fninfo {
  min-height: 56px;
  margin-top: 8px;
}
.ds-fninfo p {
  margin: 4px 0 0;
  color: var(--ds-sub);
}
.ds-evaltree,
.ds-evaltree ul {
  margin: 0;
  padding-inline-start: 18px;
  list-style: disc;
}
.ds-evaltree li {
  margin: 3px 0;
}
.ds-evaltree code {
  font-size: 12px;
}
.ds-thread {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 8px;
}
.ds-thread .ds-tmsg {
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--ds-surface-2);
}
.ds-msghead {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ds-msghead time {
  color: var(--ds-muted);
  font-size: 11.5px;
}
.ds-msghead .ds-link {
  margin-inline-start: auto;
  font-size: 11.5px;
}
.ds-thread p {
  margin: 4px 0 0;
  white-space: pre-wrap;
}
.ds-toasts {
  position: absolute;
  left: 50%;
  bottom: 70px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
}
.ds-toast {
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(560px, 90vw);
  padding: 9px 14px;
  border-radius: 8px;
  background: #1f2937;
  color: #f9fafb;
  box-shadow: var(--ds-shadow);
  pointer-events: auto;
  animation: ds-pop 0.16s ease-out;
}
.ds-toast.err {
  background: #991b1b;
}
.ds-toast .ds-link {
  color: #99f6e4;
}
.ds-auto {
  position: absolute;
  z-index: 25;
  width: 340px;
  max-height: 230px;
  margin: 0;
  padding: 4px;
  overflow: auto;
  list-style: none;
  border: 1px solid var(--ds-line);
  border-radius: 8px;
  background: var(--ds-surface);
  box-shadow: var(--ds-shadow);
}
.ds-auto li {
  display: flex;
  flex-direction: column;
  padding: 4px 8px;
  border-radius: 5px;
  cursor: pointer;
}
.ds-auto li b {
  font: 600 12.5px Consolas, Menlo, monospace;
}
.ds-auto li span {
  color: var(--ds-muted);
  font-size: 11.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-auto li.on,
.ds-auto li:hover {
  background: var(--ds-accent-soft);
}
.ds-hint,
.ds-prompt,
.ds-hover,
.ds-tip {
  position: absolute;
  z-index: 24;
  max-width: 380px;
  padding: 7px 10px;
  border: 1px solid var(--ds-line);
  border-radius: 6px;
  background: var(--ds-surface);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.14);
  font-size: 12.5px;
  pointer-events: none;
}
.ds-hint .fn {
  color: #7c3aed;
  font-weight: 600;
}
.ds-hint small {
  display: block;
  margin-top: 2px;
  color: var(--ds-muted);
}
.ds-prompt {
  background: #fffbe6;
  color: #1f2937;
}
.ds-hover {
  pointer-events: auto;
  width: 280px;
}
.ds-hcomment b {
  font-weight: 600;
}
.ds-hcomment time {
  color: var(--ds-muted);
  font-size: 11px;
}
.ds-hcomment p {
  margin: 2px 0 8px;
  white-space: pre-wrap;
}
.ds-hlink {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ds-hlink a {
  color: var(--ds-link);
  word-break: break-all;
}
.ds-hlink small,
.ds-herr {
  color: var(--ds-muted);
}
.ds-tip {
  padding: 4px 8px;
  background: #1f2937;
  color: #fff;
  border: 0;
}

/* filter popup */
.ds-filter {
  width: 290px;
}
.ds-fcond {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 2px 6px 6px;
}
.ds-filter > .ds-input {
  margin: 0 6px;
  width: calc(100% - 12px);
}
.ds-fvals {
  display: flex;
  flex-direction: column;
  max-height: 230px;
  overflow: auto;
  margin: 6px;
  padding: 4px 8px;
  border: 1px solid var(--ds-line-soft);
  border-radius: 6px;
}
.ds-fvals .ds-check.all {
  font-weight: 600;
}
.ds-fvals .ds-check span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-fbtns {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
  padding: 4px 6px 6px;
}
.ds-fbtns .ds-btn {
  min-height: 28px;
  padding: 0 10px;
}

/* panels content */
.ds-card {
  display: block;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--ds-line-soft);
  border-radius: 8px;
  background: var(--ds-surface-2);
  text-align: start;
}
button.ds-card:hover {
  border-color: var(--ds-accent);
}
.ds-card.resolved {
  opacity: 0.65;
}
.ds-cardhead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.ds-card p {
  margin: 4px 0 0;
  white-space: pre-wrap;
}
.ds-card .ds-row {
  margin-top: 8px;
}
.ds-act {
  display: flex;
  gap: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--ds-line-soft);
}
.ds-act p {
  margin: 2px 0;
}
.ds-act small {
  color: var(--ds-muted);
}
.ds-pfields {
  display: flex;
  flex-direction: column;
  max-height: 210px;
  overflow: auto;
  padding: 4px 6px;
  border: 1px solid var(--ds-line-soft);
  border-radius: 6px;
}
.ds-pfield {
  cursor: grab;
}
.ds-pareas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.ds-parea {
  min-height: 86px;
  padding: 4px 6px 6px;
  border: 1px dashed var(--ds-line);
  border-radius: 6px;
}
.ds-parea.drop {
  border-color: var(--ds-accent);
  background: var(--ds-accent-soft);
}
.ds-parea .ds-label {
  margin-top: 0;
}
.ds-chip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  margin-top: 4px;
  padding: 2px 2px 2px 8px;
  border: 1px solid var(--ds-line);
  border-radius: 5px;
  background: var(--ds-surface);
  font-size: 12px;
  cursor: grab;
}
.ds-chip span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-chip .ds-icon {
  width: 22px;
  height: 22px;
}
.ds-steps {
  margin: 0;
  padding-inline-start: 22px;
}
.ds-steps li {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.ds-preview {
  max-height: 340px;
  overflow: auto;
  border: 1px solid var(--ds-line-soft);
  border-radius: 6px;
}
.ds-preview .ds-table td,
.ds-preview .ds-table th {
  white-space: nowrap;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ds-log {
  min-height: 40px;
  max-height: 160px;
  overflow: auto;
  margin: 0;
  padding: 8px;
  border-radius: 6px;
  background: #0f172a;
  color: #a7f3d0;
  font: 12px/1.45 Consolas, Menlo, monospace;
  white-space: pre-wrap;
}
.ds-help summary {
  cursor: pointer;
  color: var(--ds-sub);
}
.ds-help pre {
  margin: 6px 0 0;
  padding: 8px;
  border-radius: 6px;
  background: var(--ds-surface-2);
  font-size: 11.5px;
  white-space: pre-wrap;
}
.ds-qatlist {
  max-height: 60vh;
  overflow: auto;
}
.ds-qatrow {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.ds-drop {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 24px 12px;
  border: 2px dashed var(--ds-line);
  border-radius: 10px;
  color: var(--ds-sub);
  cursor: pointer;
  text-align: center;
}
.ds-drop .ds-i {
  width: 30px;
  height: 30px;
}
.ds-drop.over,
.ds-drop:hover {
  border-color: var(--ds-accent);
  background: var(--ds-accent-soft);
}
.ds-sharelist {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 10px 0;
}
.ds-sharerow {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ds-sharerow > span:nth-child(2) {
  flex: 1;
  display: flex;
  flex-direction: column;
}
.ds-sharerow small {
  color: var(--ds-muted);
}
.ds-sharerow .ds-input {
  width: auto;
}
.ds-shareadd .ds-input {
  flex: 1;
  width: auto;
}
.ds-sugg {
  display: flex;
  flex-direction: column;
}
.ds-sugg small {
  margin-inline-start: auto;
  color: var(--ds-muted);
}
.ds-cons .ds-row {
  margin-bottom: 4px;
}
.ds-cons .ds-input {
  width: auto;
}
.ds-printlayout {
  display: grid;
  grid-template-columns: 230px 1fr;
  gap: 14px;
  height: 100%;
}
.ds-printopts {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.ds-printprev {
  min-height: 300px;
  border-radius: 6px;
  background: #e5e7eb;
  overflow: hidden;
}
.ds-prevframe {
  width: 100%;
  height: 100%;
  min-height: 420px;
  border: 0;
}

/* ---------- backstage (File) ---------- */
.ds-backstage {
  position: absolute;
  inset: 42px 0 0;
  z-index: 15;
  display: flex;
  background: var(--ds-surface);
}
.ds.backstage-on .ds-qat,
.ds.backstage-on .ds-people {
  visibility: hidden;
}
.ds-bsnav {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 210px;
  flex: none;
  padding: 14px 8px;
  background: var(--ds-accent);
  color: var(--ds-accent-fg);
}
.ds-bsback,
.ds-bsitem {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 7px;
  font-size: 14px;
}
.ds-bsback {
  margin-bottom: 10px;
  font-weight: 600;
}
.ds-bsitem:hover,
.ds-bsback:hover {
  background: rgba(255, 255, 255, 0.14);
}
.ds-bsitem.on {
  background: rgba(255, 255, 255, 0.22);
  font-weight: 600;
}
.ds-bsbrand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px 18px;
  font-size: 16px;
  font-weight: 700;
}
.ds-bsmain {
  flex: 1;
  min-width: 0;
  overflow: auto;
  padding: 22px 30px 40px;
}
.ds-bsmain h1 {
  margin: 0 0 18px;
  font-size: 24px;
  font-weight: 600;
}
.ds-bsmain h2 {
  margin: 24px 0 10px;
  font-size: 15px;
  font-weight: 600;
  color: var(--ds-sub);
}
.ds-banner {
  display: flex;
  gap: 12px;
  margin-bottom: 14px;
  padding: 12px 14px;
  border: 1px solid #fcd34d;
  border-radius: 10px;
  background: #fffbeb;
  color: #78350f;
}
.ds-banner p {
  margin: 2px 0 0;
}
.ds[data-theme="dark"] .ds-banner {
  border-color: #92400e;
  background: #2b1d08;
  color: #fde68a;
}
.ds-templates {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 14px;
}
.ds-tpl {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px;
  border: 1px solid var(--ds-line);
  border-radius: 10px;
  background: var(--ds-surface);
  text-align: start;
}
.ds-tpl:hover {
  border-color: var(--ds-accent);
  box-shadow: 0 4px 14px rgba(15, 118, 110, 0.12);
}
.ds-tplart {
  display: grid;
  place-items: center;
  height: 86px;
  margin-bottom: 6px;
  border-radius: 7px;
  background: linear-gradient(135deg, var(--ds-accent-soft), var(--ds-surface-2));
  color: var(--ds-accent-text);
}
.ds-tplart .ds-i {
  width: 38px;
  height: 38px;
  stroke-width: 1.3;
}
.ds-tpl small {
  color: var(--ds-muted);
}
.ds-filelist {
  display: flex;
  flex-direction: column;
}
.ds-file {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 10px;
  border-bottom: 1px solid var(--ds-line-soft);
  border-radius: 6px;
  cursor: pointer;
}
.ds-file:hover {
  background: var(--ds-hover);
}
.ds-fileicon {
  color: var(--ds-accent-text);
}
.ds-filemeta {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
}
.ds-filemeta b {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-filemeta small {
  color: var(--ds-muted);
}
.ds-openbar {
  margin-bottom: 12px;
  flex-wrap: nowrap;
}
.ds-openbar .ds-input:first-child {
  flex: 1;
}
.ds-openbar select {
  width: auto;
}
.ds-openlayout {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 18px;
}
.ds-folders {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ds-folder {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 6px;
  color: var(--ds-sub);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.ds-folder:hover {
  background: var(--ds-hover);
}
.ds-folder.on {
  background: var(--ds-accent-soft);
  color: var(--ds-accent-text);
  font-weight: 600;
}
.ds-folders .ds-link {
  margin-top: 8px;
  padding: 0 8px;
  text-align: start;
}
.ds-emptylist {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 40px 0;
  color: var(--ds-muted);
}
.ds-emptylist .ds-i {
  width: 36px;
  height: 36px;
}
.ds-info th {
  width: 190px;
}
.ds-exports {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 12px;
}
.ds-export {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto;
  column-gap: 12px;
  padding: 14px;
  border: 1px solid var(--ds-line);
  border-radius: 10px;
  text-align: start;
}
.ds-export > span {
  grid-row: span 2;
  color: var(--ds-accent-text);
}
.ds-export .ds-i {
  width: 26px;
  height: 26px;
}
.ds-export small {
  color: var(--ds-muted);
}
.ds-export:hover {
  border-color: var(--ds-accent);
}
.ds-loading {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: color-mix(in srgb, var(--ds-surface) 82%, transparent);
  color: var(--ds-sub);
}
.ds-spinner {
  width: 34px;
  height: 34px;
  border: 3px solid var(--ds-line);
  border-top-color: var(--ds-accent);
  border-radius: 50%;
  animation: ds-spin 0.8s linear infinite;
}
.ds.readonly .ds-ribbon .ds-rb:disabled {
  opacity: 0.3;
}

/* ---------- narrow screens and touch ---------- */
.ds.ds-narrow {
  height: calc(100vh - 110px);
  min-height: 480px;
  border-radius: 8px;
}
.ds.ds-narrow .ds-ribbon {
  min-height: 46px;
  padding: 3px 4px;
}
.ds.ds-narrow .ds-group {
  padding: 0 3px;
}
.ds.ds-narrow .ds-group > footer {
  display: none;
}
.ds.ds-narrow .ds-gitems.stack {
  flex-direction: row;
}
.ds.ds-narrow .ds-rb.big {
  flex-direction: row;
  height: 36px;
  min-width: 36px;
  max-width: none;
  padding: 0 6px;
}
.ds.ds-narrow .ds-rb.big > span:first-child .ds-i {
  width: 20px;
  height: 20px;
}
.ds.ds-narrow .ds-rb em,
.ds.ds-narrow .ds-col .ds-rb em {
  display: none;
}
.ds.ds-narrow .ds-col {
  flex-direction: row;
}
.ds.ds-narrow .ds-split.big {
  flex-direction: row;
}
.ds.ds-narrow .ds-split.big > .ds-rb.big {
  height: 36px;
  border-radius: 5px 0 0 5px;
}
.ds.ds-narrow .ds-split.big > .ds-rb.more {
  width: 14px;
  height: 36px;
  border-radius: 0 5px 5px 0;
}
.ds.ds-narrow .ds-rsel.font {
  width: 96px;
}
.ds.ds-narrow .ds-rsel.numfmt {
  width: 100px;
}
.ds.ds-narrow .ds-tellme,
.ds.ds-narrow .ds-savestate span,
.ds.ds-narrow .ds-share span,
.ds.ds-narrow .ds-filebtn span,
.ds.ds-narrow .ds-views,
.ds.ds-narrow .ds-zoom input,
.ds.ds-narrow .ds-mode,
.ds.ds-narrow .ds-calcstate {
  display: none;
}
.ds.ds-narrow .ds-namewrap {
  width: 84px;
}
.ds.ds-narrow .ds-side {
  position: absolute;
  inset: auto 0 0 0;
  z-index: 12;
  width: auto;
  height: 58%;
  border-inline-start: 0;
  border-top: 1px solid var(--ds-line);
  border-radius: 12px 12px 0 0;
  box-shadow: var(--ds-shadow);
}
.ds.ds-narrow .ds-backstage {
  flex-direction: column;
}
.ds.ds-narrow .ds-bsnav {
  flex-direction: row;
  width: auto;
  padding: 6px;
  overflow-x: auto;
}
.ds.ds-narrow .ds-bsbrand {
  display: none;
}
.ds.ds-narrow .ds-bsitem,
.ds.ds-narrow .ds-bsback {
  flex: none;
  padding: 7px 10px;
  margin: 0;
}
.ds.ds-narrow .ds-bsmain {
  padding: 16px;
}
.ds.ds-narrow .ds-openlayout,
.ds.ds-narrow .ds-printlayout,
.ds.ds-narrow .ds-nfpane {
  grid-template-columns: 1fr;
}
.ds.ds-narrow .ds-folders {
  flex-direction: row;
  flex-wrap: wrap;
}
.ds.ds-narrow .ds-grid2,
.ds.ds-narrow .ds-grid3 {
  grid-template-columns: 1fr;
}
.ds.ds-narrow .ds-dialog {
  width: 100%;
  max-height: 100%;
}
.ds.ds-narrow .ds-scrim {
  padding: 6px;
  place-items: end center;
}
.ds.ds-narrow .ds-scrim.modeless {
  place-items: end center;
}
.ds.ds-tiny .ds-stats span:not(:last-child) {
  display: none;
}
.ds.ds-tiny .ds-qat .ds-rb:not([data-cmd="undo"]):not([data-cmd="redo"]) {
  display: none;
}
.ds.ds-tiny .ds-title {
  width: 100%;
}
@media (pointer: coarse) {
  .ds-rb {
    min-height: 34px;
  }
  .ds-mi {
    min-height: 38px;
  }
  .ds-sheettab {
    padding: 0 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ds *,
  .ds *::before,
  .ds *::after {
    animation: none !important;
    transition: none !important;
  }
}
